#include "qms/RNDTechnicalDossierBuilder.h"
#include <sstream>
namespace dnxr { std::string RNDTechnicalDossierBuilder::buildMarkdown(const RNDTechnicalDossierInputs& i) const { std::ostringstream os; os << "# R&D Technical Dossier 0.6.5\n\n" << "## Non-human-use statement\nThis package is for simulation, bench, HIL, and medical/regulatory review only. Human-use is blocked unless independent regulatory, ethics, physician, and hardware approvals are present.\n\n" << "## Architecture\nNeural-chip-only pipeline, explicit ACK, audited state machine, replay schema v2, QMS evidence, traceability, risk controls, and release gates.\n\n" << "## HIL/bench metrics\n" << i.hilMetricsSummary << "\n\n## CTest summary\n" << i.ctestSummary << "\n\n## Static checks\n" << i.staticChecksSummary << "\n\n## Open gaps\nExternal signoffs, independent review, and external hardware bench validation remain required.\n\n## Release decision\nMedical Review Candidate / Preclinical R&D Package.\n"; return os.str(); } }
